var pending = new ConcurrentHashMap<String, CompletableFuture<Reply>>();
CompletableFuture<Reply> call(Request req) {
    var id = UUID.randomUUID().toString();
    var future = new CompletableFuture<Reply>();
    pending.put(id, future);
    future.orTimeout(5, TimeUnit.SECONDS)
          .whenComplete((r, e) -> pending.remove(id));  // cleanup on any exit
    transport.send(new Envelope(id, req));
    return future;                     // completed by the reply listener
}

try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {
    List<Future<Reply>> inFlight = requests.stream()
        .map(r -> executor.submit(
            () -> client.callBlocking(r, Duration.ofSeconds(5))))
        .toList();
    for (Future<Reply> f : inFlight) collect(f.get());
}
